}

/// Builds the nested tree eagerly from the parent links.
List<DashaNode> dashaTree(DecodedChart chart) {
  final rows = chart.dasha;
  final nodes = List<DashaNode?>.filled(rows.length, null);
  final roots = <DashaNode>[];
  for (var i = 0; i < rows.length; i++) {
    final node = DashaNode(lord: rows.lord[i], level: rows.level[i], startJd: rows.startJd[i], endJd: rows.endJd[i]);
    nodes[i] = node;
    final parent = rows.parent[i];
    if (parent < 0) {
      roots.add(node);
    } else {
      nodes[parent]!.children.add(node);
    }
  }
  return roots;
}
